{
  "components": [
    {
      "type": "claim",
      "quote": "Les investissements effectués dans des rénovations énergétiques de bâtiments peuvent déjà être déduits de l'impôt sur le revenu.",
      "gist": "Energy renovation investments are already tax-deductible from income tax."
    },
    {
      "type": "claim",
      "quote": "Avec la nouvelle loi sur l'énergie, les frais de démolition liés aux nouvelles constructions de remplacement sont désormais déductibles.",
      "gist": "Demolition costs for replacement new constructions are now tax-deductible under the new energy law."
    },
    {
      "type": "condition",
      "quote": "dans la mesure où ces dépenses ne peuvent pas être entièrement prises en compte fiscalement l'année où elles ont été effectuées.",
      "gist": "provided these expenses cannot be fully accounted for fiscally in the year they were incurred."
    },
    {
      "type": "claim",
      "quote": "Ces frais ainsi que les coûts d'investissement énergétiques sont dorénavant aussi déductibles pendant les deux périodes fiscales suivantes.",
      "gist": "These costs and energy investment costs are now also deductible over the next two tax periods."
    }
  ]
}
